import json
print("Current input analysis:")
print(f"Grid: {len(input_grid)}x{len(input_grid[0])}")

# Find unique colors and their positions
colors = {}
for r in range(len(input_grid)):
    for c in range(len(input_grid[0])):
        color = input_grid[r][c]
        if color not in colors:
            colors[color] = []
        colors[color].append((r, c))

for color, positions in sorted(colors.items()):
    print(f"Color {color}: {len(positions)} cells")

# Check different row sections to compare patterns
for section_start in [1, 8, 17, 23]:
    # Content fill rows are at section_start+1, section_start+2, section_start+3
    r = section_start + 1
    if r < len(input_grid):
        row = input_grid[r]
        print(f"\nSection {section_start}, row {r}:")
        regions_col_ranges = [(1,5), (8,12), (15,19), (22,26)]
        for i, (start, end) in enumerate(regions_col_ranges):
            vals = row[start:end+1]
            # Get fill color (middle values, excluding borders)
            if start != end and vals[1] in [2,3,8]:
                print(f"  Region {i} (cols {start}-{end}): fill={vals[1]} ({'red' if vals[1]==2 else 'green' if vals[1]==3 else 'blue'})")
            elif vals[1] == 4:
                print(f"  Region {i} (cols {start}-{end}): BORDER ONLY")

# Transform everything to Pattern A: G R R G
# Map: 2(Red)→3(Green), 8(Blue)→2(Red), 3(Green) stays 3

def normalize_to_pattern_a(grid):
    result = []
    for r in range(len(grid)):
        new_row = []
        for v in grid[r]:
            if v == 0 or v == 4:
                new_row.append(v)
            elif v == 2:  # Red → Green
                new_row.append(3)
            elif v == 8:  # Blue → Red
                new_row.append(2)
            else:
                new_row.append(v)
        result.append(new_row)
    return result

output_pa = normalize_to_pattern_a(input_grid)
print("Normalize all to Pattern A (GRRG):")
